-/* SPDX-License-Identifier: Apache-2.0
- *
- * Brings the Antora spec site into the FlatBars design system (light-first): the
- * shared seven-family token palette, IBM Plex (UI + mono), the violet accent, and
- * the FlatBars wordmark + logo in the navbar — so the spec no longer reads as "a
- * different app". Wired via the supplemental UI (antora-playbook.yml →
- * ui.supplemental_files); the head-meta partial loads the fonts and this file.
- *
- * `flatbars-tokens.css` is GENERATED from shared/flatbars-tokens.css by
- * `npm run gen:tokens` (gated by check:tokens) — the same single source the
- * tutorials and the Lab use. Both light and dark are themed: head-meta.hbs sets
- * [data-theme] on <html> before first paint (anti-flash, persisted) and adds the
- * navbar toggle; the dark chrome overrides live at the bottom of this file. */
-@import "flatbars-tokens.css";
-
-:root {
-  --font-ui: "IBM Plex Sans", ui-sans-serif, system-ui, -apple-system, sans-serif;
-  --font-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace;
-  --fb-accent: #6d28d9;
-  --fb-accent-2: #4c1d95;
-}
-
-/* ── Typography ── */
-html { font-size: 17px; }
-body, .doc, p, li, .nav, .toc, .breadcrumbs, button, input { font-family: var(--font-ui); }
-.doc h1, .doc h2, .doc h3, .doc h4, .doc h5, .doc h6, .navbar, .nav-title {
-  font-family: var(--font-ui);
-  letter-spacing: -0.01em;
-}
-code, kbd, pre, .doc .colist > table code, .hljs, .source pre, .listingblock pre {
-  font-family: var(--font-mono);
-}
-
-/* ── Top navbar: the violet brand bar + the FlatBars wordmark/logo ── */
-.navbar { background: var(--fb-accent); }
-/* Hide the stock UI's placeholder links (Home/Products/Services/Download) — the
-   spec's navigation is the left nav + the breadcrumbs, not a marketing menu. */
-.navbar .navbar-end { display: none; }
-.navbar, .navbar a, .navbar .navbar-item, .navbar .navbar-link { color: #fff; }
-.navbar .navbar-item:hover, .navbar a:hover { background: rgba(255, 255, 255, 0.12); color: #fff; }
-/* The brand link carries the logo + a mono-caps "SPEC" suffix in the wordmark style. */
-.navbar-brand .navbar-item.navbar-brand__item,
-.navbar-brand > .navbar-item:first-child {
-  font-weight: 600;
-  display: inline-flex;
-  align-items: center;
-  gap: 0.5rem;
-}
-.navbar-brand .navbar-item.navbar-brand__item::before,
-.navbar-brand > .navbar-item:first-child::before {
-  content: "";
-  width: 22px;
-  height: 22px;
-  background: url("../img/logo.svg") center / contain no-repeat;
-  flex: none;
-}
-
-/* ── Content links + accents ── */
-.doc a, .doc a:visited { color: var(--fb-accent-2); }
-.doc a:hover { color: var(--fb-accent); }
-.doc .admonitionblock.note .icon, a.page { color: var(--fb-accent-2); }
-
-/* ── Left nav: the current page in the accent ── */
-.nav-menu .is-current-page > .nav-link,
-.nav-menu a.nav-link:hover { color: var(--fb-accent-2); }
-.nav-panel-menu, .nav-menu { font-size: 0.92rem; }
-
-/* ── Inline + block code: a soft tinted plate, matching the docs site ── */
-.doc p code, .doc li code, .doc td code {
-  background: color-mix(in srgb, var(--fb-accent) 8%, #fff);
-  border-radius: 4px;
-  padding: 0.1em 0.35em;
-}
-
-/* ── Theme toggle button (head-meta.hbs appends it to the navbar) ── */
-.fb-theme-toggle {
-  margin-left: auto;
-  background: rgba(255, 255, 255, 0.14);
-  color: #fff;
-  border: 1px solid rgba(255, 255, 255, 0.28);
-  border-radius: 6px;
-  width: 30px;
-  height: 30px;
-  font-size: 15px;
-  line-height: 1;
-  cursor: pointer;
-}
-.fb-theme-toggle:hover { background: rgba(255, 255, 255, 0.26); }
-
-/* ── Dark mode — the stock UI is light-only, so override its chrome (the dark
