-const ADMONITION = {
-  NOTE: { open: ":::note", close: ":::" },
-  TIP: { open: ":::tip", close: ":::" },
-  IMPORTANT: { open: ":::note[Important]", close: ":::" },
-  CAUTION: { open: ":::caution", close: ":::" },
-  WARNING: { open: ":::caution[Warning]", close: ":::" },
-};
