-// One AsciiDoc table line → its cells (the leading pre-`|` segment dropped).
-export function splitCells(line) {
-  const segs = topLevelSplit(line).map((c) => c.trim());
-  if (segs.length && segs[0] === "") segs.shift();
-  return segs;
-}
