-    const line = lines[i];
-    if (line.trim() === "") {
-      i++;
-      continue;
-    }
-    const segs = topLevelSplit(line).map((s) => s.trim());
-    if (/^\s*\|/.test(line)) {
-      const row = segs.slice(1); // drop the empty pre-`|` segment
-      if (firstRowCount === 0) firstRowCount = row.length;
-      for (const c of row) cells.push(c);
-    } else {
